        <div class="hero-hud" aria-label="旅人状态"><span class="avatar-mini" aria-hidden="true"></span><div class="hero-status"><div class="hero-hud-top"><strong id="hero-name">星际旅人</strong><span id="level-label">LV. 1</span></div><div class="vitality-row"><span class="hud-stat-label">生命</span><div class="hearts" id="hearts" aria-label="生命"></div><span class="hud-stat-value" id="health-value">5 / 5</span></div><div class="experience-row"><span class="hud-stat-label">修为</span><div class="xp-track" id="xp-track" role="progressbar" aria-label="升级修为" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><i id="xp-bar"></i></div><span class="hud-stat-value" id="xp-value">0 / 9</span></div></div></div>
